<script setup lang="ts">
import WorkbenchNavIcon from './WorkbenchNavIcon.vue';
import {ref,onMounted,onUnmounted,computed,watch} from 'vue';
const props=defineProps<{page:string}>();const emit=defineEmits<{(e:'counts',announcements:number,updates:number):void}>();
const state=ref<any>({items:[],history:[],version:'0.2.6',authorization:{},update:null}),busy=ref(false),error=ref(''),detail=ref<any>(null),key=ref(''),downloaded=ref('');let timer:ReturnType<typeof setInterval>|undefined;
async function request(action:string,input:any={}){const r=await fetch('/desktop/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input),credentials:'same-origin'});const v=await r.json();if(!r.ok)throw Error(v.error||'本机产品服务不可用');return v;}
function apply(v:any){state.value=v;error.value=v.error||'';emit('counts',v.items.filter((x:any)=>x.kind==='announcement'&&x.localStatus==='received').length,v.items.filter((x:any)=>x.kind==='update'&&x.localStatus==='received').length+(v.update?.updateAvailable?1:0));downloaded.value=v.history.find((h:any)=>h.status==='downloaded'&&h.releaseId===v.update?.release?.id)?.releaseId||'';if(!detail.value)detail.value=v.items.find((x:any)=>x.kind==='announcement'&&['popup','maintenance'].includes(x.type)&&x.localStatus==='received')||null;}
async function refresh(remote=false){try{apply(await request(remote?'check':'state'));}catch(e:any){error.value=e.message;}}
async function act(action:string,input:any={}){busy.value=true;error.value='';try{const v=await request(action,input);if(action==='download'){downloaded.value=v.releaseId;if(!(window as any).hetunTheme){const a=document.createElement('a');a.href='/desktop/download-file?id='+encodeURIComponent(v.releaseId);a.download=v.name;a.click();}} if(action==='activate')key.value='';await refresh(action==='activate');return true;}catch(e:any){error.value=e.message;return false;}finally{busy.value=false;}}
async function open(item:any){detail.value=item;await act('ack',{id:item.id,revision:item.revision,status:'read'});}
async function close(){const item=detail.value;if(item){if(await act('ack',{id:item.id,revision:item.revision,status:item.requireConfirmation?'confirmed':'read'}))detail.value=null;}}
const announcements=computed(()=>state.value.items.filter((x:any)=>x.kind==='announcement'));
const banner=computed(()=>announcements.value.find((x:any)=>x.type==='banner'&&x.localStatus==='received'));
const release=computed(()=>state.value.update?.release);
const desktop=!!(window as any).hetunTheme;
watch(()=>props.page,async page=>{if(page==='updates')for(const item of state.value.items.filter((x:any)=>x.kind==='update'&&x.localStatus==='received'))await act('ack',{id:item.id,revision:item.revision,status:'read'});});
const force=computed(()=>state.value.update?.updateAvailable&&state.value.update?.force);
onMounted(()=>{void refresh(true);timer=setInterval(()=>void refresh(),5000);});onUnmounted(()=>clearInterval(timer));
</script>
<template>
<div v-if="banner&&!page" class="product-banner"><span>{{banner.title}}</span><button @click="open(banner)">查看公告 →</button></div>
<section v-if="page" class="product-page">
<header><div><span class="eyebrow">HETUN THEME STUDIO</span><h1>{{({announcements:'公告中心',updates:'版本更新',records:'云端记录',activation:'授权状态'} as any)[page]}}</h1><p>{{({announcements:'接收河豚终端发布的产品公告。',updates:'查看版本说明和更新记录。',records:'查看已同步到河豚终端的操作记录。',activation:'首次联网激活后自动保存授权，后续启动自动认证。'} as any)[page]}}</p></div><button :disabled="busy" @click="refresh(true)">{{busy?'正在处理…':page==='announcements'?'刷新公告':page==='records'?'同步记录':page==='activation'?'检查授权':'检查更新'}}</button></header>
<div v-if="page==='activation'&&!state.authorization.valid" class="product-card"><h2>连接河豚终端</h2><p>{{state.authorization.message||'请先使用 Key 激活，接收你的授权范围内的公告和更新。'}}</p><div class="key-row"><input v-model="key" type="password" autocomplete="off" placeholder="输入授权 Key"/><button :disabled="busy||!key" @click="act('activate',{key})">联网激活</button></div></div>
<div v-if="page==='activation'&&state.authorization.valid" class="product-card"><h2>已激活</h2><p>授权已保存在本机，无需重复输入 Key。每次启动会按授权模式自动认证。</p></div><p v-if="page!=='activation'&&!state.authorization.valid" class="sync-info">尚未激活。请在「授权状态」中完成首次激活。</p><p v-if="error" role="alert" class="product-error">{{error}}</p>
<p class="sync-info">{{state.lastSyncAt?'最后同步：'+new Date(state.lastSyncAt).toLocaleString():'尚未同步终端'}}<span v-if="state.error&&state.authorization.valid"> · {{state.error}}，保留本机消息</span></p>
<template v-if="page==='announcements'"><div v-if="!announcements.length" class="product-empty"><span><WorkbenchNavIcon name="announcements"/></span><h2>暂无公告</h2><p>终端向此授权发布公告后，会在这里显示。</p></div><button v-for="item in announcements" :key="item.id+'-'+item.revision" class="notice-row" @click="open(item)"><span><b>{{item.title}}</b><small>{{item.type==='maintenance'?'维护通知':item.type==='popup'?'弹窗公告':item.type==='banner'?'横幅公告':'产品公告'}} · {{new Date(item.publishedAt||item.createdAt).toLocaleString()}}</small></span><span>{{item.localStatus==='received'?'未读':'已读'}} →</span></button></template>
<template v-else-if="page==='updates'"><div class="product-card"><div class="release-heading"><h2>河豚主题中心</h2><span class="release-tag">当前 v{{state.version}}</span></div><template v-if="release"><h3>{{state.update.updateAvailable?'可更新':'最新版本'}} v{{release.version}} <span v-if="state.update.force">必须更新</span></h3><p class="release-notes">{{release.notes||release.description||'此版本没有附加更新说明。'}}</p><p>{{release.filename}} · {{release.bytes?Math.round(release.bytes/1024/1024)+' MB':''}}</p><button v-if="state.update.updateAvailable" :disabled="busy" @click="act('download')">{{busy?'正在下载并校验…':'下载更新包'}}</button><button v-if="downloaded&&desktop" :disabled="busy" @click="act('install',{releaseId:downloaded})">安装已校验的更新</button></template><p v-else>终端尚未向此授权提供适用于本机的更新版本。</p></div><div class="product-card"><h2>更新记录</h2><p v-if="!state.history.length">暂无下载或安装记录</p><div v-for="h in state.history" :key="h.releaseId" class="history-row"><span>v{{h.version}} · {{h.status==='installed'?'已安装':'已下载并校验'}}</span><small>{{new Date(h.at).toLocaleString()}}</small></div></div></template>
<div v-if="page==='records'" class="product-card"><h2>云端记录</h2><p>待补传 {{state.pendingRecords||0}} 条 · 终端确认后标记为已同步</p><div v-for="r in (state.recordHistory||[]).slice(0,10)" :key="r.eventId" class="history-row"><span>{{({'theme-export':'主题包生成','template-install':'模板安装','update-check':'检查更新','update-success':'更新成功','update-failed':'更新失败'} as any)[r.type]}} · 已同步</span><small>{{new Date(r.occurredAt).toLocaleString()}}</small></div><p v-if="!(state.recordHistory||[]).length">暂无已同步的操作，完成操作并连接终端后会显示。</p></div></section>
<div v-if="detail||force" class="product-overlay"><div class="product-dialog" role="dialog" aria-modal="true" aria-label="河豚终端通知"><span class="eyebrow">河豚终端通知</span><template v-if="force"><h2>需要更新主题中心</h2><p>当前版本需要更新至 v{{release?.version}}，更新说明和下载入口在版本更新中。</p><button @click="act('download')" :disabled="busy">{{busy?'正在下载…':'下载并校验更新'}}</button><button v-if="downloaded" @click="act('install',{releaseId:downloaded})">安装更新</button></template><template v-else><h2>{{detail.title}}</h2><p class="release-notes">{{detail.content}}</p><button :disabled="busy" @click="close">{{detail.requireConfirmation?'确认已阅读':'关闭'}}</button></template><p v-if="error" class="product-error">{{error}}</p></div></div>
</template>
<style scoped>
.product-page{padding:42px 48px;max-width:1200px;margin:auto;color:inherit;box-sizing:border-box;width:100%;overflow:auto;height:100%}header{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:26px}h1{font-size:30px;margin:12px 0}h2{font-size:19px;margin:0 0 16px}p{color:var(--muted,#8c8b9b);line-height:1.7}button{border:1px solid var(--line,#8f80d13b);border-radius:12px;padding:12px 18px;background:var(--accent,#7160cf);color:var(--panel,white);cursor:pointer;font-size:14px}button:disabled{opacity:.55;cursor:wait}.product-card{background:var(--panel,#88888808);border:1px solid #88888825;border-radius:18px;padding:28px;margin:20px 0}.key-row{display:flex;gap:12px}input{flex:1;min-width:0;border:1px solid #88888840;border-radius:10px;padding:12px;color:inherit;background:transparent;font-size:14px}.product-error{color:#df6767}.sync-info{font-size:12px}.notice-row{width:100%;display:flex;justify-content:space-between;text-align:left;background:#88888808;color:inherit;border-color:#88888825;margin-bottom:12px;padding:22px}small{display:block;color:var(--muted,#8c8b9b);margin-top:10px}.release-heading{display:flex;justify-content:space-between}.release-tag{color:var(--accent,#8d7adb)}.release-notes{white-space:pre-wrap;overflow-wrap:anywhere}.product-empty{text-align:center;padding:100px 20px}.product-empty svg{width:40px;height:40px}.product-empty>span{font-size:40px;color:#9b87e5;display:block;margin-bottom:20px}.history-row{padding:14px 0;border-bottom:1px solid #88888820}.product-banner{padding:12px 24px;background:#7360cf15;display:flex;justify-content:space-between;align-items:center}.product-overlay{position:fixed;inset:0;background:#11131c80;display:flex;align-items:center;justify-content:center;z-index:2000;backdrop-filter:blur(5px)}.product-dialog{background:#f6f5fc;color:#242237;width:480px;max-width:85vw;padding:36px;border-radius:24px;box-shadow:0 24px 80px #0003}.product-dialog h2{margin-top:18px}.product-dialog button{margin:8px 8px 0 0}:global(.dark) .product-dialog{background:#20212b;color:#edeaf8}@media(max-width:700px){.product-page{padding:24px}header{align-items:flex-start;flex-direction:column}}
</style>
